def collapse_whitespace(s: str) -> str:
    result: list[str] = []
    prev_was_space = False
    for ch in s:
        if ch in (" ", "\t", "\n", "\r", "\x0b", "\x0c"):
            if not prev_was_space:
                result.append(" ")
                prev_was_space = True
        else:
            result.append(ch)
            prev_was_space = False
    # Strip leading and trailing spaces
    while result and result[0] == " ":
        result.pop(0)
    while result and result[-1] == " ":
        result.pop()
    return "".join(result)
```

